#include "stdlib/blas/base/ctrsm.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/complex/float32/ctor.h"
#include <stdint.h>

/**
* Returns the real part of complex division: (bRe + i*bIm) / (aRe + i*aIm).
*/
static float cdivf_re( const float bRe, const float bIm, const float aRe, const float aIm ) {
	float denom = ( aRe * aRe ) + ( aIm * aIm );
	return ( ( bRe * aRe ) + ( bIm * aIm ) ) / denom;
}

/**
* Returns the imaginary part of complex division: (bRe + i*bIm) / (aRe + i*aIm).
*/
static float cdivf_im( const float bRe, const float bIm, const float aRe, const float aIm ) {
	float denom = ( aRe * aRe ) + ( aIm * aIm );
	return ( ( bIm * aRe ) - ( bRe * aIm ) ) / denom;
}

/**
* Solves one of the matrix equations `op(A)*X = alpha*B` or `X*op(A) = alpha*B`
* using alternative indexing semantics.
*
* @param order     storage layout
* @param side      specifies whether A appears on the left or right
* @param uplo      specifies whether upper or lower triangular part of A is used
* @param transA    transpose operation applied to A
* @param diag      specifies whether A is unit triangular
* @param M         number of rows in B
* @param N         number of columns in B
* @param alphaRe   real part of scalar constant
* @param alphaIm   imaginary part of scalar constant
* @param A         input triangular matrix (float32 interleaved re/im)
* @param strideA1  leading dimension stride of A
* @param offsetA   starting index for A
* @param B         input/output matrix (float32 interleaved re/im)
* @param strideB1  leading dimension stride of B
* @param offsetB   starting index for B
*/
void API_SUFFIX(c_ctrsm_ndarray)( const CBLAS_LAYOUT order, const CBLAS_SIDE side, const CBLAS_UPLO uplo, const CBLAS_TRANSPOSE transA, const CBLAS_DIAG diag, const CBLAS_INT M, const CBLAS_INT N, const float alphaRe, const float alphaIm, const void *A, const CBLAS_INT strideA1, const CBLAS_INT offsetA, void *B, const CBLAS_INT strideB1, const CBLAS_INT offsetB ) {
	const float *abuf = (const float *)A;
	float *bbuf = (float *)B;
	CBLAS_INT isLeft     = ( side == CblasLeft );
	CBLAS_INT isUpper    = ( uplo == CblasUpper );
	CBLAS_INT isNoTrans  = ( transA == CblasNoTrans );
	CBLAS_INT isConjTrans = ( transA == CblasConjTrans );
	CBLAS_INT isUnit     = ( diag == CblasUnit );
	CBLAS_INT isRowMajor = ( order == CblasRowMajor );
	CBLAS_INT SA1, SA2, SB1, SB2;
	CBLAS_INT i, j, k, iA, iB;
	float aRe, aIm, bRe, bIm, kbRe, kbIm, tRe, tIm;

	if ( M == 0 || N == 0 ) {
		return;
	}
	if ( isRowMajor ) {
		SA1 = strideA1;
		SA2 = 1;
		SB1 = strideB1;
		SB2 = 1;
	} else {
		SA1 = 1;
		SA2 = strideA1;
		SB1 = 1;
		SB2 = strideB1;
	}

	/* Scale B by alpha */
	if ( alphaRe != 1.0f || alphaIm != 0.0f ) {
		for ( i = 0; i < M; i++ ) {
			for ( j = 0; j < N; j++ ) {
				iB = ( offsetB + ( i * SB1 ) + ( j * SB2 ) ) * 2;
				bRe = bbuf[ iB ];
				bIm = bbuf[ iB + 1 ];
				bbuf[ iB ]     = ( alphaRe * bRe ) - ( alphaIm * bIm );
				bbuf[ iB + 1 ] = ( alphaRe * bIm ) + ( alphaIm * bRe );
			}
		}
	}
	if ( alphaRe == 0.0f && alphaIm == 0.0f ) {
		return;
	}

	if ( isLeft ) {
		if ( isNoTrans ) {
			if ( isUpper ) {
				for ( j = 0; j < N; j++ ) {
					for ( k = M - 1; k >= 0; k-- ) {
						iB = ( offsetB + ( k * SB1 ) + ( j * SB2 ) ) * 2;
						bRe = bbuf[ iB ];
						bIm = bbuf[ iB + 1 ];
						if ( bRe != 0.0f || bIm != 0.0f ) {
							if ( isUnit == 0 ) {
								iA = ( offsetA + ( k * SA1 ) + ( k * SA2 ) ) * 2;
								aRe = abuf[ iA ];
								aIm = abuf[ iA + 1 ];
								bbuf[ iB ]     = cdivf_re( bRe, bIm, aRe, aIm );
								bbuf[ iB + 1 ] = cdivf_im( bRe, bIm, aRe, aIm );
								bRe = bbuf[ iB ];
								bIm = bbuf[ iB + 1 ];
							}
							for ( i = 0; i < k; i++ ) {
								iA = ( offsetA + ( i * SA1 ) + ( k * SA2 ) ) * 2;
								aRe = abuf[ iA ];
								aIm = abuf[ iA + 1 ];
								iB = ( offsetB + ( i * SB1 ) + ( j * SB2 ) ) * 2;
								bbuf[ iB ]     -= ( aRe * bRe ) - ( aIm * bIm );
								bbuf[ iB + 1 ] -= ( aRe * bIm ) + ( aIm * bRe );
							}
						}
					}
				}
			} else {
				for ( j = 0; j < N; j++ ) {
					for ( k = 0; k < M; k++ ) {
						iB = ( offsetB + ( k * SB1 ) + ( j * SB2 ) ) * 2;
						bRe = bbuf[ iB ];
						bIm = bbuf[ iB + 1 ];
						if ( bRe != 0.0f || bIm != 0.0f ) {
							if ( isUnit == 0 ) {
								iA = ( offsetA + ( k * SA1 ) + ( k * SA2 ) ) * 2;
								aRe = abuf[ iA ];
								aIm = abuf[ iA + 1 ];
								bbuf[ iB ]     = cdivf_re( bRe, bIm, aRe, aIm );
								bbuf[ iB + 1 ] = cdivf_im( bRe, bIm, aRe, aIm );
								bRe = bbuf[ iB ];
								bIm = bbuf[ iB + 1 ];
							}
							for ( i = k + 1; i < M; i++ ) {
								iA = ( offsetA + ( i * SA1 ) + ( k * SA2 ) ) * 2;
								aRe = abuf[ iA ];
								aIm = abuf[ iA + 1 ];
								iB = ( offsetB + ( i * SB1 ) + ( j * SB2 ) ) * 2;
								bbuf[ iB ]     -= ( aRe * bRe ) - ( aIm * bIm );
								bbuf[ iB + 1 ] -= ( aRe * bIm ) + ( aIm * bRe );
							}
						}
					}
				}
			}
		} else {
			/* Transpose or conjugate-transpose */
			if ( isUpper ) {
				for ( j = 0; j < N; j++ ) {
					for ( i = 0; i < M; i++ ) {
						iB = ( offsetB + ( i * SB1 ) + ( j * SB2 ) ) * 2;
						tRe = bbuf[ iB ];
						tIm = bbuf[ iB + 1 ];
						for ( k = 0; k < i; k++ ) {
							iA = ( offsetA + ( k * SA1 ) + ( i * SA2 ) ) * 2;
							aRe = abuf[ iA ];
							aIm = ( isConjTrans ) ? -abuf[ iA + 1 ] : abuf[ iA + 1 ];
							iB = ( offsetB + ( k * SB1 ) + ( j * SB2 ) ) * 2;
							bRe = bbuf[ iB ];
							bIm = bbuf[ iB + 1 ];
							tRe -= ( aRe * bRe ) - ( aIm * bIm );
							tIm -= ( aRe * bIm ) + ( aIm * bRe );
						}
						if ( isUnit == 0 ) {
							iA = ( offsetA + ( i * SA1 ) + ( i * SA2 ) ) * 2;
							aRe = abuf[ iA ];
							aIm = ( isConjTrans ) ? -abuf[ iA + 1 ] : abuf[ iA + 1 ];
							iB = ( offsetB + ( i * SB1 ) + ( j * SB2 ) ) * 2;
							bbuf[ iB ]     = cdivf_re( tRe, tIm, aRe, aIm );
							bbuf[ iB + 1 ] = cdivf_im( tRe, tIm, aRe, aIm );
						} else {
							iB = ( offsetB + ( i * SB1 ) + ( j * SB2 ) ) * 2;
							bbuf[ iB ]     = tRe;
							bbuf[ iB + 1 ] = tIm;
						}
					}
				}
			} else {
				for ( j = 0; j < N; j++ ) {
					for ( i = M - 1; i >= 0; i-- ) {
						iB = ( offsetB + ( i * SB1 ) + ( j * SB2 ) ) * 2;
						tRe = bbuf[ iB ];
						tIm = bbuf[ iB + 1 ];
						for ( k = i + 1; k < M; k++ ) {
							iA = ( offsetA + ( k * SA1 ) + ( i * SA2 ) ) * 2;
							aRe = abuf[ iA ];
							aIm = ( isConjTrans ) ? -abuf[ iA + 1 ] : abuf[ iA + 1 ];
							iB = ( offsetB + ( k * SB1 ) + ( j * SB2 ) ) * 2;
							bRe = bbuf[ iB ];
							bIm = bbuf[ iB + 1 ];
							tRe -= ( aRe * bRe ) - ( aIm * bIm );
							tIm -= ( aRe * bIm ) + ( aIm * bRe );
						}
						if ( isUnit == 0 ) {
							iA = ( offsetA + ( i * SA1 ) + ( i * SA2 ) ) * 2;
							aRe = abuf[ iA ];
							aIm = ( isConjTrans ) ? -abuf[ iA + 1 ] : abuf[ iA + 1 ];
							iB = ( offsetB + ( i * SB1 ) + ( j * SB2 ) ) * 2;
							bbuf[ iB ]     = cdivf_re( tRe, tIm, aRe, aIm );
							bbuf[ iB + 1 ] = cdivf_im( tRe, tIm, aRe, aIm );
						} else {
							iB = ( offsetB + ( i * SB1 ) + ( j * SB2 ) ) * 2;
							bbuf[ iB ]     = tRe;
							bbuf[ iB + 1 ] = tIm;
						}
					}
				}
			}
		}
	} else {
		/* Right side */
		if ( isNoTrans ) {
			if ( isUpper ) {
				for ( j = 0; j < N; j++ ) {
					for ( i = 0; i < M; i++ ) {
						iB = ( offsetB + ( i * SB1 ) + ( j * SB2 ) ) * 2;
						bRe = bbuf[ iB ];
						bIm = bbuf[ iB + 1 ];
						for ( k = 0; k < j; k++ ) {
							iA = ( offsetA + ( k * SA1 ) + ( j * SA2 ) ) * 2;
							aRe = abuf[ iA ];
							aIm = abuf[ iA + 1 ];
							iB = ( offsetB + ( i * SB1 ) + ( k * SB2 ) ) * 2;
							kbRe = bbuf[ iB ];
							kbIm = bbuf[ iB + 1 ];
							bRe -= ( aRe * kbRe ) - ( aIm * kbIm );
							bIm -= ( aRe * kbIm ) + ( aIm * kbRe );
						}
						if ( isUnit == 0 ) {
							iA = ( offsetA + ( j * SA1 ) + ( j * SA2 ) ) * 2;
							aRe = abuf[ iA ];
							aIm = abuf[ iA + 1 ];
							iB = ( offsetB + ( i * SB1 ) + ( j * SB2 ) ) * 2;
							bbuf[ iB ]     = cdivf_re( bRe, bIm, aRe, aIm );
							bbuf[ iB + 1 ] = cdivf_im( bRe, bIm, aRe, aIm );
						} else {
							iB = ( offsetB + ( i * SB1 ) + ( j * SB2 ) ) * 2;
							bbuf[ iB ]     = bRe;
							bbuf[ iB + 1 ] = bIm;
						}
					}
				}
			} else {
				for ( j = N - 1; j >= 0; j-- ) {
					for ( i = 0; i < M; i++ ) {
						iB = ( offsetB + ( i * SB1 ) + ( j * SB2 ) ) * 2;
						bRe = bbuf[ iB ];
						bIm = bbuf[ iB + 1 ];
						for ( k = j + 1; k < N; k++ ) {
							iA = ( offsetA + ( k * SA1 ) + ( j * SA2 ) ) * 2;
							aRe = abuf[ iA ];
							aIm = abuf[ iA + 1 ];
							iB = ( offsetB + ( i * SB1 ) + ( k * SB2 ) ) * 2;
							kbRe = bbuf[ iB ];
							kbIm = bbuf[ iB + 1 ];
							bRe -= ( aRe * kbRe ) - ( aIm * kbIm );
							bIm -= ( aRe * kbIm ) + ( aIm * kbRe );
						}
						if ( isUnit == 0 ) {
							iA = ( offsetA + ( j * SA1 ) + ( j * SA2 ) ) * 2;
							aRe = abuf[ iA ];
							aIm = abuf[ iA + 1 ];
							iB = ( offsetB + ( i * SB1 ) + ( j * SB2 ) ) * 2;
							bbuf[ iB ]     = cdivf_re( bRe, bIm, aRe, aIm );
							bbuf[ iB + 1 ] = cdivf_im( bRe, bIm, aRe, aIm );
						} else {
							iB = ( offsetB + ( i * SB1 ) + ( j * SB2 ) ) * 2;
							bbuf[ iB ]     = bRe;
							bbuf[ iB + 1 ] = bIm;
						}
					}
				}
			}
		} else {
			/* Right, transpose or conjugate-transpose */
			if ( isUpper ) {
				for ( k = N - 1; k >= 0; k-- ) {
					for ( i = 0; i < M; i++ ) {
						iB = ( offsetB + ( i * SB1 ) + ( k * SB2 ) ) * 2;
						tRe = bbuf[ iB ];
						tIm = bbuf[ iB + 1 ];
						if ( isUnit == 0 ) {
							iA = ( offsetA + ( k * SA1 ) + ( k * SA2 ) ) * 2;
							aRe = abuf[ iA ];
							aIm = ( isConjTrans ) ? -abuf[ iA + 1 ] : abuf[ iA + 1 ];
							tRe = cdivf_re( tRe, tIm, aRe, aIm );
							tIm = cdivf_im( bbuf[ iB ], bbuf[ iB + 1 ], aRe, aIm );
						}
						bbuf[ iB ]     = tRe;
						bbuf[ iB + 1 ] = tIm;
						for ( j = 0; j < k; j++ ) {
							iA = ( offsetA + ( j * SA1 ) + ( k * SA2 ) ) * 2;
							aRe = abuf[ iA ];
							aIm = ( isConjTrans ) ? -abuf[ iA + 1 ] : abuf[ iA + 1 ];
							iB = ( offsetB + ( i * SB1 ) + ( j * SB2 ) ) * 2;
							bbuf[ iB ]     -= ( aRe * tRe ) - ( aIm * tIm );
							bbuf[ iB + 1 ] -= ( aRe * tIm ) + ( aIm * tRe );
						}
					}
				}
			} else {
				for ( k = 0; k < N; k++ ) {
					for ( i = 0; i < M; i++ ) {
						iB = ( offsetB + ( i * SB1 ) + ( k * SB2 ) ) * 2;
						tRe = bbuf[ iB ];
						tIm = bbuf[ iB + 1 ];
						if ( isUnit == 0 ) {
							iA = ( offsetA + ( k * SA1 ) + ( k * SA2 ) ) * 2;
							aRe = abuf[ iA ];
							aIm = ( isConjTrans ) ? -abuf[ iA + 1 ] : abuf[ iA + 1 ];
							tRe = cdivf_re( tRe, tIm, aRe, aIm );
							tIm = cdivf_im( bbuf[ iB ], bbuf[ iB + 1 ], aRe, aIm );
						}
						bbuf[ iB ]     = tRe;
						bbuf[ iB + 1 ] = tIm;
						for ( j = k + 1; j < N; j++ ) {
							iA = ( offsetA + ( k * SA1 ) + ( j * SA2 ) ) * 2;
							aRe = abuf[ iA ];
							aIm = ( isConjTrans ) ? -abuf[ iA + 1 ] : abuf[ iA + 1 ];
							iB = ( offsetB + ( i * SB1 ) + ( j * SB2 ) ) * 2;
							bbuf[ iB ]     -= ( aRe * tRe ) - ( aIm * tIm );
							bbuf[ iB + 1 ] -= ( aRe * tIm ) + ( aIm * tRe );
						}
					}
				}
			}
		}
	}
}
